## 3. Result-Generation Logic (form data → recommendation)

The ICSI recommendation is computed by an inline `evaluate()` function defined directly in the Compass page (not in a separate lib file). The generic `pdfExport.ts` (below) only renders the result to a printable/PDF document.

Source: `client/src/pages/ICSICompass.tsx`

```tsx
type SpermConcentration = "normal" | "mild" | "moderate" | "severe" | "azoospermia";

interface ICSIInputs {
  spermConcentration: SpermConcentration;
  totalMotileCount: number;
  morphologyPercent: number;
  priorIVFFailedFertilization: boolean;
  priorIVFLowFertilization: boolean;
  antispermAntibodies: boolean;
  obstructiveAzoospermia: boolean;
  nonObstructiveAzoospermia: boolean;
  surgicalSpermRetrieval: boolean;
  frozenSperm: boolean;
  unexplainedIVFFailure: boolean;
}

const defaultInputs: ICSIInputs = {
  spermConcentration: "normal", totalMotileCount: 0, morphologyPercent: 0,
  priorIVFFailedFertilization: false, priorIVFLowFertilization: false,
  antispermAntibodies: false, obstructiveAzoospermia: false,
  nonObstructiveAzoospermia: false, surgicalSpermRetrieval: false,
  frozenSperm: false, unexplainedIVFFailure: false,
};

function evaluate(inputs: ICSIInputs) {
  const warnings: string[] = [];
  const rationale: string[] = [];
  const references = [
    "Practice Committee of the ASRM. Intracytoplasmic sperm injection (ICSI) for non-male factor indications: a committee opinion. Fertil Steril. 2020;114(2):239-245.",
    "Van Steirteghem A, et al. High fertilization and implantation rates after intracytoplasmic sperm injection. Hum Reprod. 1993;8(7):1061-1066.",
    "Palermo G, et al. Pregnancies after intracytoplasmic injection of single spermatozoon into an oocyte. Lancet. 1992;340(8810):17-18.",
  ];

  let recommendation = "not_indicated";
  let procedure = "";
  let cor = "I";
  let loe = "A";

  const hasAbsoluteIndication = inputs.spermConcentration === "severe" ||
    inputs.spermConcentration === "azoospermia" ||
    inputs.obstructiveAzoospermia || inputs.nonObstructiveAzoospermia ||
    inputs.surgicalSpermRetrieval || inputs.priorIVFFailedFertilization ||
    inputs.antispermAntibodies;

  const hasRelativeIndication = inputs.spermConcentration === "moderate" ||
    inputs.priorIVFLowFertilization || inputs.frozenSperm ||
    inputs.unexplainedIVFFailure || inputs.morphologyPercent < 4;

  if (hasAbsoluteIndication) {
    recommendation = "indicated";
    procedure = "ICSI — absolute indication";
    cor = "I"; loe = "A";
    if (inputs.surgicalSpermRetrieval || inputs.obstructiveAzoospermia || inputs.nonObstructiveAzoospermia) {
      rationale.push("Surgical sperm retrieval: ICSI is required — conventional IVF insemination is not possible with surgically retrieved sperm.");
    }
    if (inputs.priorIVFFailedFertilization) {
      rationale.push("Prior IVF with failed fertilization: ICSI is indicated to overcome fertilization failure.");
    }
    if (inputs.antispermAntibodies) {
      rationale.push("Antisperm antibodies: ICSI bypasses the zona pellucida, overcoming antibody-mediated fertilization failure.");
    }
    if (inputs.spermConcentration === "severe" || inputs.spermConcentration === "azoospermia") {
      rationale.push("Severe male factor: total motile count is insufficient for conventional IVF insemination.");
    }
  } else if (hasRelativeIndication) {
    recommendation = "consider";
    procedure = "ICSI — relative indication (shared decision-making)";
    cor = "IIa"; loe = "B";
    rationale.push("Relative indication present: ICSI may improve fertilization rates but evidence for routine use in non-male factor is mixed (ASRM 2020).");
    warnings.push("ASRM 2020: ICSI for non-male factor indications is not routinely recommended without specific clinical justification.");
  } else {
    recommendation = "not_indicated";
    procedure = "Conventional IVF insemination — ICSI not indicated";
    cor = "III"; loe = "B";
    rationale.push("No male factor or other ICSI indication identified. Conventional IVF insemination is appropriate.");
    warnings.push("Routine ICSI for all IVF cycles is not supported by evidence and may not be covered by insurance without documented indication.");
  }

  return { recommendation, procedure, cor, loe, warnings, rationale, references };
}
```

The result is also serialized to a printable assessment document via the generic export helper below.

Source: `client/src/lib/pdfExport.ts`

```typescript
// PDF export using browser print API

export interface PDFExportOptions {
  filename: string;
  title: string;
  content: string;
  metadata?: {
    date?: string;
    module?: string;
    [key: string]: any;
  };
}

/**
 * Export assessment results as PDF
 */
export async function exportAssessmentPDF(options: PDFExportOptions): Promise<void> {
  const { filename, title, content, metadata } = options;

  const htmlContent = `
    <!DOCTYPE html>
    <html>
    <head>
      <meta charset="UTF-8">
      <title>${title}</title>
      <style>
        * {
          margin: 0;
          padding: 0;
          box-sizing: border-box;
        }
        body {
          font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen', 'Ubuntu', 'Cantarell', sans-serif;
          line-height: 1.6;
          color: #333;
          background: white;
          padding: 20px;
        }
        .header {
          border-bottom: 3px solid #e11d48;
          padding-bottom: 20px;
          margin-bottom: 30px;
        }
        .header h1 {
          font-size: 28px;
          color: #1e293b;
          margin-bottom: 10px;
        }
        .metadata {
          font-size: 12px;
          color: #64748b;
          display: flex;
          gap: 20px;
          flex-wrap: wrap;
        }
        .metadata-item {
          display: flex;
          gap: 5px;
        }
        .metadata-label {
          font-weight: 600;
          color: #475569;
        }
        .content {
          margin-top: 20px;
        }
        .section {
          margin-bottom: 30px;
          page-break-inside: avoid;
        }
        .section-title {
          font-size: 18px;
          font-weight: 600;
          color: #1e293b;
          border-left: 4px solid #e11d48;
          padding-left: 15px;
          margin-bottom: 15px;
          margin-top: 20px;
        }
        .section-content {
          background: #f8fafc;
          padding: 15px;
          border-radius: 6px;
          margin-bottom: 15px;
        }
        .field {
          margin-bottom: 12px;
          display: flex;
          justify-content: space-between;
          align-items: flex-start;
        }
        .field-label {
          font-weight: 600;
          color: #475569;
          min-width: 150px;
        }
        .field-value {
          color: #1e293b;
          text-align: right;
          flex: 1;
        }
        table {
          width: 100%;
          border-collapse: collapse;
          margin: 15px 0;
        }
        th {
          background: #e2e8f0;
          padding: 10px;
          text-align: left;
          font-weight: 600;
          color: #1e293b;
          border: 1px solid #cbd5e1;
        }
        td {
          padding: 10px;
          border: 1px solid #cbd5e1;
          color: #475569;
        }
        tr:nth-child(even) {
          background: #f8fafc;
        }
        .footer {
          margin-top: 40px;
          padding-top: 20px;
          border-top: 1px solid #e2e8f0;
          font-size: 11px;
          color: #64748b;
          text-align: center;
        }
        .disclaimer {
          background: #fef2f2;
          border: 1px solid #fecaca;
          padding: 12px;
          border-radius: 4px;
          font-size: 12px;
          color: #7f1d1d;
          margin-top: 20px;
        }
        @media print {
          body {
            padding: 0;
          }
        }
      </style>
    </head>
    <body>
      <div class="header">
        <h1>${title}</h1>
        ${metadata ? `
          <div class="metadata">
            ${metadata.date ? `<div class="metadata-item"><span class="metadata-label">Date:</span> <span>${metadata.date}</span></div>` : ''}
            ${metadata.module ? `<div class="metadata-item"><span class="metadata-label">Module:</span> <span>${metadata.module}</span></div>` : ''}
          </div>
        ` : ''}
      </div>
      <div class="content">
        ${content}
      </div>
      <div class="footer">
        <p>This document was generated by Clinical Compass™. Please review and verify all information before use.</p>
      </div>
    </body>
    </html>
  `;

  const element = document.createElement('div');
  element.innerHTML = htmlContent;

  const opt = {
    margin: 10,
    filename: `${filename}.pdf`,
    image: { type: 'jpeg', quality: 0.98 },
    html2canvas: { scale: 2 },
    jsPDF: { orientation: 'portrait', unit: 'mm', format: 'a4' },
  };

  // Use html2pdf if available, otherwise use a simple approach
  try {
    if (typeof (window as any).html2pdf !== 'undefined') {
      (window as any).html2pdf().set(opt).from(element).save();
    } else {
      // Fallback: open print dialog
      const printWindow = window.open('', '', 'width=800,height=600');
      if (printWindow) {
        printWindow.document.write(htmlContent);
        printWindow.document.close();
        printWindow.print();
      }
    }
  } catch (error) {
    console.error('PDF export failed:', error);
    // Fallback: open print dialog
    const printWindow = window.open('', '', 'width=800,height=600');
    if (printWindow) {
      printWindow.document.write(htmlContent);
      printWindow.document.close();
      printWindow.print();
    }
  }
}

/**
 * Generate HTML content for assessment results
 */
export function generateAssessmentHTML(data: {
  title: string;
  demographics?: {
    age?: number;
    sex?: string;
    bmi?: number;
  };
  findings?: Array<{ label: string; value: string }>;
  recommendation?: string;
  details?: string;
}): string {
  let html = '';

  if (data.demographics) {
    html += `
      <div class="section">
        <div class="section-title">Patient Demographics</div>
        <div class="section-content">
          ${data.demographics.age ? `<div class="field"><span class="field-label">Age:</span> <span class="field-value">${data.demographics.age} years</span></div>` : ''}
          ${data.demographics.sex ? `<div class="field"><span class="field-label">Sex:</span> <span class="field-value">${data.demographics.sex}</span></div>` : ''}
          ${data.demographics.bmi ? `<div class="field"><span class="field-label">BMI:</span> <span class="field-value">${data.demographics.bmi}</span></div>` : ''}
        </div>
      </div>
    `;
  }

  if (data.findings && data.findings.length > 0) {
    html += `
      <div class="section">
        <div class="section-title">Clinical Findings</div>
        <div class="section-content">
          ${data.findings.map(f => `<div class="field"><span class="field-label">${f.label}:</span> <span class="field-value">${f.value}</span></div>`).join('')}
        </div>
      </div>
    `;
  }

  if (data.recommendation) {
    html += `
      <div class="section">
        <div class="section-title">Clinical Recommendation</div>
        <div class="section-content">
          <p>${data.recommendation}</p>
        </div>
      </div>
    `;
  }

  if (data.details) {
    html += `
      <div class="section">
        <div class="section-content">
          ${data.details}
        </div>
      </div>
    `;
  }

  html += `
    <div class="disclaimer">
      <strong>Disclaimer:</strong> This assessment is generated by Clinical Compass™ clinical decision support tool and is intended to assist physicians in clinical decision-making. It should not replace professional medical judgment. All recommendations should be reviewed and validated by the treating physician before clinical implementation.
    </div>
  `;

  return html;
}
```


